MODULES = ['owner_feishu_transport.py', 'owner_feishu_history.py', 'owner_feishu_claim_guard.py', 'owner_feishu_ledger_endpoint.py', 'owner_feishu_bridge_cycle.py', 'owner_feishu_https.py']
MODULE_DIGESTS = {'owner_feishu_transport.py': '96e53b23576d6c23ba569b8e88e524f85a51fe01a115a13a0163884353d7222c', 'owner_feishu_history.py': 'f3c9be72b3c40315b5fad6c73def20828de1d83182ad7b0de659371ddabed3b1', 'owner_feishu_claim_guard.py': '71816cc0acc497e34ebc273d4b6e3e079894bad351e88419a239cb2c6ce32c26', 'owner_feishu_ledger_endpoint.py': 'c7da7991ee9fe4f63b4ab4fb71fffbe725e98c0fadc5ecda22b9fa8c2d9abe0c', 'owner_feishu_bridge_cycle.py': '85fe28d120d9c6cc932e0619966947ea2b5e5b3d57cd2e5ee9a6144a446e8add', 'owner_feishu_https.py': '4db02fd39c5b6a27b3faa185760679efacb82285ab377630463b903923e03a98'}

def apply(root):
    root=pathlib.Path(root).resolve()
    if root.name!='xuanjun-p2-package':raise ValueError('EXACT_PACKAGE_ROOT_REQUIRED')
    # Prevalidate every source and destination before editing any file.
    for path,spec in PATCHES.items():
        target=root/path
        if target.is_symlink() or hashlib.sha256(target.read_bytes()).hexdigest()!=spec['sha256']:
            raise ValueError('FEISHU_RUNTIME_BASE_DRIFT:'+path)
        text=target.read_text()
        for old,new in spec['edits']:
            if text.count(old)!=1:raise ValueError('FEISHU_RUNTIME_SNIPPET_DRIFT:'+path)
            text=text.replace(old,new)
    template=root/'deploy/p2-owner-feishu-binding.json.template'
    if template.exists():raise ValueError('FEISHU_BINDING_TEMPLATE_EXISTS')
    for name in MODULES:
        module=pathlib.Path(__file__).resolve().parent/name
        if module.is_symlink() or hashlib.sha256(module.read_bytes()).hexdigest()!=MODULE_DIGESTS[name]:
            raise ValueError('FEISHU_MODULE_DIGEST_MISMATCH')
        if (root/'stage1'/name).exists():raise ValueError('FEISHU_RUNTIME_TARGET_EXISTS')
    for path,spec in PATCHES.items():
        target=root/path;text=target.read_text()
        for old,new in spec['edits']:text=text.replace(old,new)
        target.write_text(text)
    for name in MODULES:
        shutil.copyfile(str(pathlib.Path(__file__).resolve().parent/name),str(root/'stage1'/name))
    template.write_text('{"app_id":"@@APP_ID@@","chat_id":"@@CHAT_ID@@","package_sha256":"@@PACKAGE_SHA256@@"}\n')
    manifest_path=root/'deploy/integration-manifest.json'
    manifest=json.loads(manifest_path.read_text())
    names=set(manifest['files'])|{'stage1/'+name for name in MODULES}|{'deploy/p2-owner-feishu-binding.json.template'}
    manifest['files']={name:hashlib.sha256((root/name).read_bytes()).hexdigest() for name in sorted(names)}
    manifest_path.write_text(json.dumps(manifest,sort_keys=True,indent=2)+'\n')
    print('FEISHU_RUNTIME_OVERLAY_APPLIED_NOT_RELEASED')

if __name__=='__main__':apply(sys.argv[1])
